import{_ as e,o as t,c as s,a4 as r}from"./chunks/framework.BRzJ4ijD.js";const m=JSON.parse('{"title":"SLO / SLI / Error Budget","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/monitor/slo.md","filePath":"system-design/monitor/slo.md","lastUpdated":1788475713000}'),n={name:"system-design/monitor/slo.md"};function i(l,a,o,p,d,u){return t(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="slo-sli-error-budget" tabindex="-1">SLO / SLI / Error Budget <a class="header-anchor" href="#slo-sli-error-budget" aria-label="Permalink to &quot;SLO / SLI / Error Budget&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Google SRE (Site Reliability Engineering) 团队在 2016 年提出的<strong>服务可靠性工程</strong>核心 framework:</p><ol><li><strong>SLI (Service Level Indicator)</strong>: 服务可用性的 <strong>量化 metric</strong> — &quot;对用户来说什么是好的&quot; (e.g., availability = 200 OK success rate, latency P99 &lt; 100ms)。</li><li><strong>SLO (Service Level Objective)</strong>: 对 SLI 设置的 <strong>目标值</strong> — &quot;我们希望 99.9% 的请求在 100ms 内成功&quot;。</li><li><strong>Error Budget</strong>: 允许的&quot;失败空间&quot; = <code>1 − SLO</code>. 如果 error budget 花光, 必须 freeze 新 feature release 稳定平台。</li></ol><p>这三者是非主观的、<strong>数据驱动的 reliability roadmap</strong> — 不再是&quot;系统要快而稳&quot;, 而是&quot;系统 P95 &lt; 100ms in 99.9% windows&quot; measurable 的 roadmap。本章深入 SLI 设计、SLO 设定 (30 天 / 7 天 rolling windows) , Error Budget 管理与 burn rate, 经典事故 (Netflix startup error budget runout) 。</p><hr><h2 id="一、sli-service-level-indicator" tabindex="-1">一、SLI (Service Level Indicator) <a class="header-anchor" href="#一、sli-service-level-indicator" aria-label="Permalink to &quot;一、SLI (Service Level Indicator)&quot;">​</a></h2><h3 id="必须量化" tabindex="-1">必须量化 <a class="header-anchor" href="#必须量化" aria-label="Permalink to &quot;必须量化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>SLI 类型</th><th>度量</th><th>说明</th></tr></thead><tbody><tr><td><strong>Availability</strong></td><td><code>success_count / total_requests</code></td><td>200/2xx HTTP, gRPC OK, 业务定义成功</td></tr><tr><td><strong>Latency</strong></td><td><code>histogram_quantile(0.99, request_latency_seconds)</code></td><td>P99 延迟</td></tr><tr><td><strong>Throughput</strong></td><td><code>rate(requests_total[1m])</code></td><td>容量用度</td></tr><tr><td><strong>Durability</strong></td><td><code>writes_committed / writes_accepted</code></td><td>储存器持久性</td></tr></tbody></table><h3 id="选-sli-的两个维度" tabindex="-1">选 SLI 的两个维度 <a class="header-anchor" href="#选-sli-的两个维度" aria-label="Permalink to &quot;选 SLI 的两个维度&quot;">​</a></h3><ul><li><strong>用户面 (User-Facing)</strong>: 直接影响 UX —— API 返回、页面渲染、搜索页面 latency</li><li><strong>关键面 (Critical)</strong>: 服务 health — CPU allocation, QPS, disk IO &gt; 90%</li></ul><p><strong>规则</strong>: Alert 只设定于用户面 SLI, 不 alert 于基础设施面 SLI (除非是 capacity接近 cap)。</p><h3 id="critical-path-breakdown" tabindex="-1">Critical Path Breakdown <a class="header-anchor" href="#critical-path-breakdown" aria-label="Permalink to &quot;Critical Path Breakdown&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User: POST /api/order</span></span>
<span class="line"><span>SLI 1: API availability = (200||201 responses)/(total requests)</span></span>
<span class="line"><span>SLI 2: P99 latency &lt; 500ms (checkout response time)</span></span>
<span class="line"><span>SLI 3: checkout error rate &lt; 0.1% (order failure/non-retryable)</span></span></code></pre></div><h3 id="sli-granularity" tabindex="-1">SLI Granularity <a class="header-anchor" href="#sli-granularity" aria-label="Permalink to &quot;SLI Granularity&quot;">​</a></h3><p>Don&#39;t 整体统 一 每 endpoint? 区分:</p><ul><li><code>pages/</code>: 首页 P99&lt;200ms, 商品列表 P99&lt;300ms, 搜索 P99&lt;1000ms?</li><li><code>critical/</code>: checkout API P99&lt;500ms, availability 99.9% 以上</li></ul><p>若 critical SLI 的 错误预算烧得很快, 整个生产速度必须下降 直至 稳定。</p><hr><h2 id="二、slo-service-level-objective" tabindex="-1">二、SLO (Service Level Objective) <a class="header-anchor" href="#二、slo-service-level-objective" aria-label="Permalink to &quot;二、SLO (Service Level Objective)&quot;">​</a></h2><h3 id="目标值" tabindex="-1">目标值 <a class="header-anchor" href="#目标值" aria-label="Permalink to &quot;目标值&quot;">​</a></h3><p>SLO = SLI 达到目标 <strong>probability over time window</strong>:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>P</mi><mrow><mi>S</mi><mi>L</mi><mi>I</mi></mrow></msub><mo>≥</mo><msub><mi>P</mi><mrow><mi>t</mi><mi>a</mi><mi>r</mi><mi>g</mi><mi>e</mi><mi>t</mi></mrow></msub><mo separator="true">,</mo><mspace width="1em"></mspace><mtext>over 30 days</mtext></mrow><annotation encoding="application/x-tex">P_{SLI} \\geq P_{target}, \\quad \\text{over 30 days} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0576em;">S</span><span class="mord mathnormal mtight">L</span><span class="mord mathnormal mtight" style="margin-right:0.0785em;">I</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.9805em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">over 30 days</span></span></span></span></span></span></p><p>例: &quot;checkout API availability SLI = 99.9% over 30 days&quot;.</p><h3 id="定义-window-滚动" tabindex="-1">定义 Window (滚动) <a class="header-anchor" href="#定义-window-滚动" aria-label="Permalink to &quot;定义 Window (滚动)&quot;">​</a></h3><ul><li><strong>30 days</strong>: 稳定测量, 忽略短暂 spikes</li><li><strong>7 days</strong>: 快速反馈 (适配 fast iterations)</li><li><strong>1 day</strong>: 基本上 用于 reactive hotfix</li></ul><p>实际常用 rolling 30 day for quarterly reliability review; 7 day for burn rate monitoring.</p><h3 id="典型-slo-数" tabindex="-1">典型 SLO 数 <a class="header-anchor" href="#典型-slo-数" aria-label="Permalink to &quot;典型 SLO 数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>服务</th><th>可用性 SLO</th><th>年度误差预算</th></tr></thead><tbody><tr><td>关键金融交易</td><td>99.99% (&quot;four nines&quot;)</td><td>~52 分钟/y</td></tr><tr><td>电商 checkout</td><td>99.9%</td><td>~8.8 小时/year</td></tr><tr><td>社交 feed</td><td>99.5%</td><td>~1.6 天/y</td></tr><tr><td>新闻 feed</td><td>99%</td><td>~3.65 天/y</td></tr><tr><td>内部 工具 / admin</td><td>99%</td><td>~3.65 天/year</td></tr><tr><td>Dev/测试</td><td>no SLO</td><td>不要 SLO; just 容忍 down time</td></tr></tbody></table><p><strong>定 SLO 高于 99.9% (~44min/m) 每一额外 nine costs $100K+ per 服务业 is realistic budget no matter.</strong></p><p>规则: **不高于 99.99% 除非你 真正 花 钱 operation 花到 T5 teams. **</p><h3 id="_99-9-误解" tabindex="-1">&quot;99.9%&quot; 误解 <a class="header-anchor" href="#_99-9-误解" aria-label="Permalink to &quot;&quot;99.9%&quot; 误解&quot;">​</a></h3><p>99.9% = 0.1% 不可用 over window = 43.2 min / month.</p><p>实际运作 服务 可 99.5-99.9 range; most internal services never above 99.9% because chronic change speed compromises stability.</p><hr><h2 id="三、error-budget" tabindex="-1">三、Error Budget <a class="header-anchor" href="#三、error-budget" aria-label="Permalink to &quot;三、Error Budget&quot;">​</a></h2><h3 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h3><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>Budget</mtext><mo>=</mo><mo stretchy="false">(</mo><mn>1</mn><mo>−</mo><mi>S</mi><mi>L</mi><mi>O</mi><mi mathvariant="normal">_</mi><mrow><mi>t</mi><mi>a</mi><mi>r</mi><mi>g</mi><mi>e</mi><mi>t</mi></mrow><mo stretchy="false">)</mo><mo>×</mo><mtext>total_time_window</mtext></mrow><annotation encoding="application/x-tex">\\text{Budget} = (1 - SLO\\_{target}) \\times \\text{total\\_time\\_window} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">Budget</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1.06em;vertical-align:-0.31em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal">L</span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mord" style="margin-right:0.0278em;">_</span><span class="mord"><span class="mord mathnormal">t</span><span class="mord mathnormal">a</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mord mathnormal">e</span><span class="mord mathnormal">t</span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1.0044em;vertical-align:-0.31em;"></span><span class="mord text"><span class="mord">total_time_window</span></span></span></span></span></span></p><p>例: SLO=99.9%, window=30 days, Budget = 0.1% × 30 × 24 × 60 = 43.2 min 可 down window.</p><p>每 30 天 roll. 但 SLI burn rate shows speed consuming budget.</p><h3 id="什么时候-burn" tabindex="-1">什么时候 Burn? <a class="header-anchor" href="#什么时候-burn" aria-label="Permalink to &quot;什么时候 Burn?&quot;">​</a></h3><ul><li>每 failed 请求 count. e.g., non-200 status.</li><li>每 timeout 响应 time.</li><li>SLI metric 计算 burn rate.</li></ul><h3 id="burn-rate-阈值" tabindex="-1">Burn Rate 阈值 <a class="header-anchor" href="#burn-rate-阈值" aria-label="Permalink to &quot;Burn Rate 阈值&quot;">​</a></h3><p>Google SRE 建议 6 倍 burn rate triggering <strong>immediate incident alert</strong>:</p><table tabindex="0"><thead><tr><th>Severity</th><th>Burn rate</th><th>时间 to exhaust budget</th></tr></thead><tbody><tr><td>Critical (immediate page)</td><td>14.4× (budget consumed ~6h)</td><td>~6 hours</td></tr><tr><td>High alert (almost exhausting)</td><td>6×</td><td>~24 hours</td></tr><tr><td>Medium (warning)</td><td>1×</td><td>~7 days</td></tr><tr><td>Low (tracking)</td><td>&lt; 0.2x</td><td>long, not urgent</td></tr></tbody></table><h3 id="freeze-policy" tabindex="-1">Freeze Policy <a class="header-anchor" href="#freeze-policy" aria-label="Permalink to &quot;Freeze Policy&quot;">​</a></h3><p>若 当前 month的 error budget 接近 exhausted, must 对 &quot;新feature release&quot; 施加 freeze: 只接受 bug fix + reliability project, 直到 budget 恢复 (next window smooth). 这利地 forcing teams spend time on reliability over features.</p><p>&quot;If you always burning error budget, you are in feature-debt vs reliability debt.&quot;</p><h3 id="error-budget-recovery" tabindex="-1">Error Budget Recovery <a class="header-anchor" href="#error-budget-recovery" aria-label="Permalink to &quot;Error Budget Recovery&quot;">​</a></h3><p>恢复:</p><ul><li>idle window 自动 recover; 30 天 rolling 后 新 start.</li><li>Service after problem fixed 可用增加 allowance: SLI observation critical.</li><li>Manual reset 不推荐; data driven only.</li></ul><hr><h2 id="四、如何先设定-slo" tabindex="-1">四、如何先设定 SLO？ <a class="header-anchor" href="#四、如何先设定-slo" aria-label="Permalink to &quot;四、如何先设定 SLO？&quot;">​</a></h2><h3 id="step-1-setup-base-slis" tabindex="-1">Step 1: Setup Base SLIs <a class="header-anchor" href="#step-1-setup-base-slis" aria-label="Permalink to &quot;Step 1: Setup Base SLIs&quot;">​</a></h3><p>选 2-4 SLIs for critical user journeys:</p><ul><li>checkout page api 可用性</li><li>home page P99 latency</li><li>search query time P99</li></ul><h3 id="step-2-collect-baseline-sli" tabindex="-1">Step 2: Collect baseline SLI <a class="header-anchor" href="#step-2-collect-baseline-sli" aria-label="Permalink to &quot;Step 2: Collect baseline SLI&quot;">​</a></h3><p>Record SLI for 2 weeks; compute current P99, current success rate → baseline.</p><h3 id="step-3-set-slo" tabindex="-1">Step 3: Set SLO <a class="header-anchor" href="#step-3-set-slo" aria-label="Permalink to &quot;Step 3: Set SLO&quot;">​</a></h3><p>SLO_initial = measured_baseline + headroom (15-30% improvement).</p><p>Avoid giving overly ambitious SLO that simply doesn&#39;t reflect actual capability; reduce in first week error budget catastrophically burn → teams switch to reliability <strong>now</strong>.</p><h3 id="step-4-monitor-burn-rate" tabindex="-1">Step 4: Monitor Burn Rate <a class="header-anchor" href="#step-4-monitor-burn-rate" aria-label="Permalink to &quot;Step 4: Monitor Burn Rate&quot;">​</a></h3><p>Set 2 alert levels:</p><ul><li>burn rate 1x: warning, 让 on-call check</li><li>burn rate 6x: page critical, must intervene</li></ul><h3 id="step-5-hold-slo-reviews" tabindex="-1">Step 5: Hold SLO Reviews <a class="header-anchor" href="#step-5-hold-slo-reviews" aria-label="Permalink to &quot;Step 5: Hold SLO Reviews&quot;">​</a></h3><p>Monthly SLO review: 检查: 满足 SLO (under budget), 讨论 &quot;which new features 该 deploy?&quot;</p><p>&quot;When the error budget is gone, you are on a feature freeze.&quot;</p><hr><h2 id="五、network-infrastructure-slo-多层次" tabindex="-1">五、Network / Infrastructure SLO 多层次 <a class="header-anchor" href="#五、network-infrastructure-slo-多层次" aria-label="Permalink to &quot;五、Network / Infrastructure SLO 多层次&quot;">​</a></h2><h3 id="example-netflix-cdn-slo" tabindex="-1">Example: Netflix CDN SLO <a class="header-anchor" href="#example-netflix-cdn-slo" aria-label="Permalink to &quot;Example: Netflix CDN SLO&quot;">​</a></h3><ul><li>Netflix 视频 分发 by CDN (Open Connect appliance CDN), with target 99.99% delivery success for each ISP.</li><li>Each POP also self-enforce SLO of 100% CDN bandwidth usage under load.</li><li>Goal: 99.9% user sessions not affect by network pause.</li></ul><h3 id="google-cloud-gcp-networking-slo" tabindex="-1">Google Cloud GCP Networking SLO <a class="header-anchor" href="#google-cloud-gcp-networking-slo" aria-label="Permalink to &quot;Google Cloud GCP Networking SLO&quot;">​</a></h3><ul><li>Cloud Load Balancing ensures 99.99% 连通性 multi-region anycast IP.</li><li>Compute Engine per instance uptime guarantee = 99.95%.</li></ul><h3 id="aws-s3-durability-slo" tabindex="-1">AWS S3 Durability SLO <a class="header-anchor" href="#aws-s3-durability-slo" aria-label="Permalink to &quot;AWS S3 Durability SLO&quot;">​</a></h3><p>Durability objective 11 9 (don&#39;t lose data) even using EC; SLI is loss-probability per year 1E-11.</p><hr><h2 id="六、error-budget-与-developer-velocity" tabindex="-1">六、Error Budget 与 developer velocity <a class="header-anchor" href="#六、error-budget-与-developer-velocity" aria-label="Permalink to &quot;六、Error Budget 与 developer velocity&quot;">​</a></h2><p>&quot;Move fast &amp; break things&quot; vs &quot;高 reliability commit&quot;:</p><ul><li>With error budget 未用: develop 大 feature, risk 允许 小 spike failure.</li><li>With error budget 烧完: <strong>feature freeze</strong> develop 全面停止, 只做 reliability hardening. 一旦 新 feature deploy → 再 fail the SLO。</li></ul><p>工具: feature flag + canary deployment + gradual rollout. 一旦 canary 触发 error spike, 停止 rollout.</p><h3 id="example-spotify-—-slo-feature-velocity" tabindex="-1">Example: Spotify — SLO &amp; feature velocity <a class="header-anchor" href="#example-spotify-—-slo-feature-velocity" aria-label="Permalink to &quot;Example: Spotify — SLO &amp; feature velocity&quot;">​</a></h3><p>Spotify 模型 &quot;SLO for each Squad&quot;. 每 team autonomy control service + SLO. If service within SLO, team 选择 部署 scale deploy; 若 跌破 SLO.冻结 features, hotfix + re 升.</p><h3 id="google-sre-process" tabindex="-1">Google SRE process <a class="header-anchor" href="#google-sre-process" aria-label="Permalink to &quot;Google SRE process&quot;">​</a></h3><p>每 季 monitoring data SLO — 提前 end of quarter 20% error budget 未 用 clean bill go deploy feat for next quarter.</p><hr><h2 id="七、prometheus-slo-burn-rate-示例" tabindex="-1">七、Prometheus SLO / Burn rate 示例 <a class="header-anchor" href="#七、prometheus-slo-burn-rate-示例" aria-label="Permalink to &quot;七、Prometheus SLO / Burn rate 示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># SLI: availability of orders API</span></span>
<span class="line"><span>sum(rate(http_requests_total{status=~&quot;2..&quot;, path=&quot;/orders&quot;}[30d]))</span></span>
<span class="line"><span>/</span></span>
<span class="line"><span>sum(rate(http_requests_total{path=&quot;/orders&quot;}[30d]))</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Burn rate over 1h (~14.4x burn alert):</span></span>
<span class="line"><span>(</span></span>
<span class="line"><span>  sum(rate(http_requests_total{status!~&quot;2..&quot;,path=&quot;/orders&quot;}[1h]))</span></span>
<span class="line"><span>  /</span></span>
<span class="line"><span>  sum(rate(http_requests_total{path=&quot;/orders&quot;}[1h]))</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>&gt; 14.4 * (1 - 0.999)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># PromQL label 并告警:</span></span>
<span class="line"><span>- alert: HighErrorBudgetBurn</span></span>
<span class="line"><span>  expr: |</span></span>
<span class="line"><span>    sum(rate(http_requests_total{status!~&quot;2..&quot;}[1h]))</span></span>
<span class="line"><span>    / sum(rate(http_requests_total[1h]))</span></span>
<span class="line"><span>    &gt; 14.4 * 0.001</span></span>
<span class="line"><span>  for: 5m</span></span>
<span class="line"><span>  labels:</span></span>
<span class="line"><span>    severity: critical</span></span>
<span class="line"><span>  annotations:</span></span>
<span class="line"><span>    summary: &quot;Error budget burning fast on order service&quot;</span></span></code></pre></div><hr><h2 id="八、典型事故" tabindex="-1">八、典型事故 <a class="header-anchor" href="#八、典型事故" aria-label="Permalink to &quot;八、典型事故&quot;">​</a></h2><h3 id="netflix-error-budget-overturned" tabindex="-1">Netflix Error Budget Overturned <a class="header-anchor" href="#netflix-error-budget-overturned" aria-label="Permalink to &quot;Netflix Error Budget Overturned&quot;">​</a></h3><p>Netflix 在某 release 中, 部分 Netflix 公开影视的 SRT 渲染中断, 用户 interface 无响应。 Error budget 3 小时 burn rate 5x; 触发 页面 alarm pipeline 暂 停 red 支. 后续 server-level hotfix.</p><h3 id="spotify-mobile-app-slo-过低设定" tabindex="-1">Spotify mobile app SLO 过低设定 <a class="header-anchor" href="#spotify-mobile-app-slo-过低设定" aria-label="Permalink to &quot;Spotify mobile app SLO 过低设定&quot;">​</a></h3><p>设定 &quot;99% availability&quot;, 实际 meaning 24 hours/month allowed downtime. 体验差 but teams had budget unused because always within threshold. Upgrade SLO to 99.5% → burn faster =&gt; teams take reliability seriously.</p><h3 id="gcp-incorrect-slo-duration-setting" tabindex="-1">GCP Incorrect SLO Duration setting <a class="header-anchor" href="#gcp-incorrect-slo-duration-setting" aria-label="Permalink to &quot;GCP Incorrect SLO Duration setting&quot;">​</a></h3><p>某 Google Cloud service SLO 30 days; last 30 days averaged OK, but two days of severe downtime earlier month hidden over average. Fix: burn rate alert (短 window) 辅 30 day SLO 计算.</p><h3 id="unused-downward-error-budget-shift" tabindex="-1">Unused Downward Error Budget Shift <a class="header-anchor" href="#unused-downward-error-budget-shift" aria-label="Permalink to &quot;Unused Downward Error Budget Shift&quot;">​</a></h3><p>某 enterprise SaaS provider 通知 用 Slack meeting: &quot;We have 3 days downtime within most LEA years&quot;. Moving error budget into that new month causes team always &quot;behind&quot;. Fix: SLO start each batch rolling window not annual.</p><hr><h2 id="九、易错清单" tabindex="-1">九、易错清单 <a class="header-anchor" href="#九、易错清单" aria-label="Permalink to &quot;九、易错清单&quot;">​</a></h2><ol><li><strong>SLO 不要定太高</strong>: start at current measurement + 5-10% buffer.</li><li><strong>SLO 必对用户有意义</strong>: NOT infrastructure metric (CPU, memory, disk IO) — only user-experienced.</li><li><strong>Burn rate computed over multiple windows</strong>: 1h for 14x burn alert, 6h for 3x burn w/ regression.</li><li><strong>不要在 downtime 后 reset error budget</strong>: rolling window 自动 recover; avoid manual清除.</li><li><strong>要有 &quot;错误预算用于 feature support&quot;</strong>: 分配一部分 to risk tolerance features deploy.</li><li><strong>Error budget must be visible to dev</strong>: monitor and dashboard within dev&#39;s view (every PR into production links burn chart).</li><li><strong>Monthly SLI/SLO review meeting</strong>: guaranteed reliability culture persists.</li></ol><hr><h2 id="十、这一章带走的东西" tabindex="-1">十、这一章带走的东西 <a class="header-anchor" href="#十、这一章带走的东西" aria-label="Permalink to &quot;十、这一章带走的东西&quot;">​</a></h2><ol><li>SLI (量化 metric) + SLO (目标), Error Budget 是 允 许失败.</li><li>Error Budget 烧完 ⇒ 强制性 &quot;stop feature, fix reliability&quot;.</li><li>Burn rate &gt; 6× → critical page; &gt; 14.4× → within hours budget exhaustion.</li><li>Rolling window 30 days for SLO review; 1h/6h burn rate alert.</li><li>SLO should be user-facing; never infrastructure SLO only.</li><li>PromQL 例: burn rate alert with 14.4×(1-SLO) trigger.</li><li>Spotify/Netflix/Google SRE 实战 case all center around SLO+Error Budget: &quot;Move fast unless you burn budget&quot;.</li></ol><hr><p>下一节 → <a href="./stack">监控 Stack</a></p>`,105)])])}const h=e(n,[["render",i]]);export{m as __pageData,h as default};
